CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY, title TEXT, model TEXT, preview TEXT, message_count INTEGER NOT NULL, profile_id TEXT, pinned BOOLEAN NOT NULL, archived BOOLEAN NOT NULL, folder_id TEXT, pin_sort_order INTEGER, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, timestamp TEXT, tool_call_id TEXT, provider_id TEXT, prompt_tokens INTEGER, completion_tokens INTEGER, total_tokens INTEGER, cache_read_tokens INTEGER, cache_write_tokens INTEGER, context_window INTEGER, elapsed_ms INTEGER);
CREATE TABLE IF NOT EXISTS profiles (id TEXT PRIMARY KEY, slug TEXT UNIQUE, name TEXT NOT NULL, icon TEXT, environment TEXT NOT NULL, container_image TEXT, container_id TEXT, persona TEXT, remote_ssh_server_id TEXT, container_dockerfile TEXT, location_aware BOOLEAN NOT NULL, pinned_limit INTEGER NOT NULL, sort_order INTEGER NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS folders (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, name TEXT NOT NULL, sort_order INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scheduled_tasks (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, session_id TEXT, name TEXT NOT NULL, trigger_kind TEXT NOT NULL, trigger_type TEXT NOT NULL, cron_expression TEXT, run_at TEXT, script_path TEXT, script_inline TEXT, needs_network BOOLEAN NOT NULL, approved BOOLEAN NOT NULL, enabled BOOLEAN NOT NULL, last_run_at TEXT, last_run_status TEXT, last_run_output TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS scheduled_task_runs (id TEXT PRIMARY KEY, task_id TEXT NOT NULL, profile_id TEXT NOT NULL, session_id TEXT, invocation_kind TEXT NOT NULL, status TEXT NOT NULL, output TEXT, started_at TEXT NOT NULL, finished_at TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS push_subscriptions (id TEXT PRIMARY KEY, endpoint TEXT NOT NULL, p256dh TEXT NOT NULL, auth TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile_memories (id TEXT PRIMARY KEY, profile_id TEXT NOT NULL, memory_type TEXT NOT NULL, content TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile_memory_jobs (profile_id TEXT PRIMARY KEY, dirty BOOLEAN NOT NULL, last_processed_at TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS profile_container_mounts (profile_id TEXT NOT NULL, ordinal INTEGER NOT NULL, host_path TEXT NOT NULL, container_path TEXT NOT NULL, access TEXT NOT NULL, PRIMARY KEY (profile_id, ordinal));
CREATE TABLE IF NOT EXISTS message_permission_requests (message_id INTEGER PRIMARY KEY, request_id TEXT NOT NULL, mode TEXT NOT NULL, script TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS message_permission_responses (message_id INTEGER PRIMARY KEY, request_id TEXT NOT NULL, approved BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS message_workspace_requests (message_id INTEGER PRIMARY KEY, request_id TEXT NOT NULL, path TEXT NOT NULL, reason TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS message_workspace_responses (message_id INTEGER PRIMARY KEY, request_id TEXT NOT NULL, approved BOOLEAN NOT NULL);
CREATE TABLE IF NOT EXISTS message_ask_user_requests (message_id INTEGER PRIMARY KEY, request_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS message_ask_user_request_questions (message_id INTEGER NOT NULL, ordinal INTEGER NOT NULL, section TEXT NOT NULL, question TEXT NOT NULL, multi_select BOOLEAN NOT NULL, PRIMARY KEY (message_id, ordinal));
CREATE TABLE IF NOT EXISTS message_ask_user_request_options (message_id INTEGER NOT NULL, question_ordinal INTEGER NOT NULL, option_ordinal INTEGER NOT NULL, value TEXT NOT NULL, PRIMARY KEY (message_id, question_ordinal, option_ordinal));
CREATE TABLE IF NOT EXISTS message_ask_user_responses (message_id INTEGER PRIMARY KEY, request_id TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS message_ask_user_response_answers (message_id INTEGER NOT NULL, ordinal INTEGER NOT NULL, section TEXT NOT NULL, answer_kind TEXT NOT NULL, custom_text TEXT, PRIMARY KEY (message_id, ordinal));
CREATE TABLE IF NOT EXISTS message_ask_user_response_selected_options (message_id INTEGER NOT NULL, answer_ordinal INTEGER NOT NULL, option_ordinal INTEGER NOT NULL, value TEXT NOT NULL, PRIMARY KEY (message_id, answer_ordinal, option_ordinal));
CREATE TABLE IF NOT EXISTS session_pending_message_entries (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, delivery_mode TEXT NOT NULL, content TEXT NOT NULL, hidden_context_xml TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_pending_message_attachments (message_id INTEGER NOT NULL, ordinal INTEGER NOT NULL, attachment_id TEXT NOT NULL, name TEXT NOT NULL, attachment_type TEXT NOT NULL, url TEXT NOT NULL, upload_data_url TEXT, text_content TEXT, PRIMARY KEY (message_id, ordinal));
CREATE TABLE IF NOT EXISTS session_pending_ask_user_requests_v2 (request_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_pending_ask_user_questions_v2 (request_id TEXT NOT NULL, ordinal INTEGER NOT NULL, section TEXT NOT NULL, question TEXT NOT NULL, multi_select BOOLEAN NOT NULL, PRIMARY KEY (request_id, ordinal));
CREATE TABLE IF NOT EXISTS session_pending_ask_user_question_options_v2 (request_id TEXT NOT NULL, question_ordinal INTEGER NOT NULL, option_ordinal INTEGER NOT NULL, value TEXT NOT NULL, PRIMARY KEY (request_id, question_ordinal, option_ordinal));
CREATE TABLE IF NOT EXISTS context_debug_snapshot_headers (session_id TEXT PRIMARY KEY, timestamp TEXT NOT NULL, model TEXT NOT NULL, provider_id TEXT NOT NULL, prompt TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS context_debug_snapshot_prompt_attachments (session_id TEXT NOT NULL, ordinal INTEGER NOT NULL, url TEXT NOT NULL, PRIMARY KEY (session_id, ordinal));
CREATE TABLE IF NOT EXISTS context_debug_snapshot_messages (session_id TEXT NOT NULL, ordinal INTEGER NOT NULL, role TEXT NOT NULL, content TEXT NOT NULL, tool_call_id TEXT, PRIMARY KEY (session_id, ordinal));
CREATE TABLE IF NOT EXISTS context_debug_snapshot_message_attachments (session_id TEXT NOT NULL, message_ordinal INTEGER NOT NULL, attachment_ordinal INTEGER NOT NULL, url TEXT NOT NULL, PRIMARY KEY (session_id, message_ordinal, attachment_ordinal));
CREATE TABLE IF NOT EXISTS context_debug_snapshot_message_tool_calls (session_id TEXT NOT NULL, message_ordinal INTEGER NOT NULL, tool_call_ordinal INTEGER NOT NULL, name TEXT NOT NULL, PRIMARY KEY (session_id, message_ordinal, tool_call_ordinal));
CREATE TABLE IF NOT EXISTS notification_mailbox (id TEXT PRIMARY KEY, title TEXT NOT NULL, body TEXT NOT NULL, session_id TEXT, callback_context_xml TEXT, callback_message TEXT, status TEXT NOT NULL, sent_count INTEGER NOT NULL, last_error TEXT, delivered_at TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS request_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, timestamp TEXT NOT NULL, model TEXT NOT NULL, provider_id TEXT NOT NULL, prompt_tokens INTEGER, completion_tokens INTEGER, total_tokens INTEGER, cache_read_tokens INTEGER, cache_write_tokens INTEGER, context_window INTEGER, elapsed_ms INTEGER NOT NULL, ok BOOLEAN NOT NULL, error TEXT);
CREATE TABLE IF NOT EXISTS network_access_logs (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT, profile_id TEXT, source TEXT NOT NULL, mode TEXT NOT NULL, domain TEXT NOT NULL, port INTEGER NOT NULL, allowed BOOLEAN NOT NULL, reason TEXT, timestamp TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_runtimes (session_id TEXT PRIMARY KEY, state TEXT NOT NULL, browser_takeover_active BOOLEAN NOT NULL, browser_takeover_alert_pending BOOLEAN NOT NULL, terminal_task_id TEXT, terminal_output_file TEXT, terminal_output_preview TEXT, terminal_input_notice TEXT, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_plans (session_id TEXT PRIMARY KEY, plan_state TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_run_leases (session_id TEXT PRIMARY KEY, active BOOLEAN NOT NULL, cancellation_requested BOOLEAN NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_pending_permissions (request_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, mode TEXT NOT NULL, script TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS session_pending_workspace (request_id TEXT PRIMARY KEY, session_id TEXT NOT NULL, path TEXT NOT NULL, reason TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_messages_session_id ON messages(session_id);
CREATE INDEX IF NOT EXISTS idx_messages_session_role ON messages(session_id, role);
CREATE INDEX IF NOT EXISTS idx_sessions_profile_id ON sessions(profile_id);
CREATE INDEX IF NOT EXISTS idx_sessions_archived ON sessions(archived, updated_at);
CREATE INDEX IF NOT EXISTS idx_folders_profile_id ON folders(profile_id);
CREATE INDEX IF NOT EXISTS idx_scheduled_tasks_profile ON scheduled_tasks(profile_id);
CREATE INDEX IF NOT EXISTS idx_profile_memories_profile ON profile_memories(profile_id, memory_type);
CREATE INDEX IF NOT EXISTS idx_profile_memory_jobs_dirty_updated_at ON profile_memory_jobs(dirty, updated_at);
CREATE INDEX IF NOT EXISTS idx_profile_container_mounts_profile ON profile_container_mounts(profile_id, ordinal);
CREATE INDEX IF NOT EXISTS idx_message_permission_requests_request_id ON message_permission_requests(request_id);
CREATE INDEX IF NOT EXISTS idx_message_permission_responses_request_id ON message_permission_responses(request_id);
CREATE INDEX IF NOT EXISTS idx_message_workspace_requests_request_id ON message_workspace_requests(request_id);
CREATE INDEX IF NOT EXISTS idx_message_workspace_responses_request_id ON message_workspace_responses(request_id);
CREATE INDEX IF NOT EXISTS idx_message_ask_user_requests_request_id ON message_ask_user_requests(request_id);
CREATE INDEX IF NOT EXISTS idx_message_ask_user_responses_request_id ON message_ask_user_responses(request_id);
CREATE INDEX IF NOT EXISTS idx_session_pending_message_entries_session_created ON session_pending_message_entries(session_id, created_at);
CREATE INDEX IF NOT EXISTS idx_session_pending_message_attachments_message ON session_pending_message_attachments(message_id, ordinal);
CREATE INDEX IF NOT EXISTS idx_session_pending_ask_user_requests_v2_session ON session_pending_ask_user_requests_v2(session_id);
CREATE INDEX IF NOT EXISTS idx_context_debug_snapshot_headers_timestamp ON context_debug_snapshot_headers(timestamp);
CREATE INDEX IF NOT EXISTS idx_notification_mailbox_status_created_at ON notification_mailbox(status, created_at);
CREATE INDEX IF NOT EXISTS idx_request_logs_timestamp ON request_logs(timestamp);
CREATE INDEX IF NOT EXISTS idx_request_logs_session_timestamp ON request_logs(session_id, timestamp);
CREATE INDEX IF NOT EXISTS idx_network_access_logs_timestamp ON network_access_logs(timestamp);
CREATE INDEX IF NOT EXISTS idx_network_access_logs_session ON network_access_logs(session_id, timestamp);
CREATE INDEX IF NOT EXISTS idx_session_pending_permissions_session ON session_pending_permissions(session_id);
CREATE INDEX IF NOT EXISTS idx_session_pending_workspace_session ON session_pending_workspace(session_id);
CREATE TABLE IF NOT EXISTS session_tasks (session_id TEXT PRIMARY KEY, content TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS global_memory (id INTEGER PRIMARY KEY CHECK (id = 1), content TEXT NOT NULL, updated_at TEXT NOT NULL);
PRAGMA journal_mode=WAL;
